from pathlib import Path
import html,re
ROOT=Path(__file__).resolve().parents[1]
D=ROOT/'dist'
SPOTIFY='https://open.spotify.com/show/17Y9zFZ4U2Cj9gBXXc7O8G'
MAP='https://www.google.com/maps/search/?api=1&query=427+Matheson+Avenue+Winnipeg+Manitoba'
def link(url,text,cls='button'):
 return f'<a class="{cls}" href="{url}">{text} <span aria-hidden="true">↗</span></a>'
def image(name,alt,cls=''):
 return f'<img class="{cls}" src="assets/{name}" alt="{alt}" loading="lazy">'
def header(active):
 def navlink(file,text):return f'<a href="{file}.html"'+(' aria-current="page"' if file==active else '')+f'>{text}</a>'
 return '<header><div class="wrap navigation"><a class="brand" href="index.html" aria-label="Faith Life home"><img src="assets/logo.png" alt="Faith Life Community Ministries"></a><button id="menu" aria-label="Open navigation" aria-controls="nav" aria-expanded="false">Menu <span aria-hidden="true">☰</span></button><nav id="nav" aria-label="Main navigation">'+navlink('about','About us')+navlink('ministries','Ministries')+navlink('messages','Messages')+'<details class="nav-resources"><summary>Resources <span aria-hidden="true">⌄</span></summary><div>'+navlink('articles','Articles')+navlink('news','News')+navlink('events','Events')+'</div></details>'+navlink('contact','Contact')+link('visit.html','Plan your visit','button white')+'</nav></div></header>'
def footer():
 return '''<footer><div class="wrap"><div class="footer-grid"><div><a class="brand" href="index.html" aria-label="Faith Life home"><img src="assets/logo.png" alt="Faith Life Community Ministries"></a><p>Bible-based.<br>Christ-centered.<br>Spirit-led.</p></div><div><h3>Our church</h3><a href="about.html#team">Pastors & elders</a><a href="about.html#beliefs">Statement of faith</a><a href="ministries.html">Ministries</a><a href="visit.html">Plan your visit</a></div><div><h3>Explore</h3><a href="messages.html">Messages</a><a href="articles.html">Articles</a><a href="news.html">News</a><a href="events.html">Events</a></div><div><h3>Come say hello</h3><p>427 Matheson Avenue<br>Winnipeg, MB R2V 3A7</p><a href="contact.html">Contact us ↗</a></div></div><div class="footer-bottom"><span>© <span id="year">2026</span> Faith Life Community Ministries</span><a href="#top">Back to top ↑</a></div></div></footer>'''
def page(file,title,description,body):
 s=f'<!doctype html><html lang="en" id="top"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{html.escape(title)} | Faith Life Community Ministries</title><meta name="description" content="{html.escape(description)}"><link rel="stylesheet" href="style.css?v=5"><link rel="stylesheet" href="pages.css?v=5"></head><body class="interior"><a class="skip" href="#main">Skip to content</a>{header(file)}<main id="main">{body}</main>{footer()}<script src="app.js?v=5"></script></body></html>'
 (D/(file+'.html')).write_text(s)
def hero(title,description,photo=None,alt='',actions=''):
 copy=f'<div class="inner-hero-copy"><a class="breadcrumb" href="index.html">Home <span aria-hidden="true">/</span></a><h1>{title}</h1><p>{description}</p>{actions}</div>'
 return f'<section class="inner-hero {"with-photo" if photo else "text-hero"}"><div class="wrap">{copy}'+(f'<div class="inner-hero-photo">{image(photo,alt)}</div>' if photo else '')+'</div></section>'
def cta(title='Take your next step.',text='We would love to help you find your place in the Faith Life community.',url='contact.html',button='Connect with us'):
 return f'<section class="section closing-cta"><div class="wrap"><div><h2>{title}</h2><p>{text}</p></div>{link(url,button,"button white")}</div></section>'
# ABOUT
pastors=[('Ian Abad','Lead Pastor','IA'),('Wendell Olojan','Pastor Emeritus','WO'),('Jaden Esquejo','Youth Pastor','JE')]
elders=['Henry Francisco','Freddie Calvadores','Albino Ferrer','Norie De Castro','Nito Alarilla']
beliefs=[('God','One God, eternally existing as Father, Son, and Holy Spirit.','Genesis 1:1; 2 Corinthians 13:14'),('Jesus Christ','Fully God and fully human, Jesus died for sin, rose again, and will return.','John 1:1–5; 1 Corinthians 15:3–4'),('The Holy Spirit','The Spirit indwells believers, guides them in truth, and equips them for service.','John 14:16–17; Galatians 5:25'),('The Bible','God’s inspired, trustworthy Word is our supreme authority for faith and life.','2 Timothy 3:16; 2 Peter 1:20–21'),('Humanity','Created in God’s image, all people are sinners and need reconciliation with God through Christ.','Genesis 1:27; Romans 3:23'),('Salvation','Salvation is God’s gift of grace, received through repentance and faith in Jesus Christ.','Ephesians 2:8–9; Romans 6:23'),('Eternity','Heaven and hell are real. Eternal life with God comes through Jesus Christ.','John 3:16; Revelation 20:15'),('Baptism & the Lord’s Supper','Believer’s baptism by immersion and the Lord’s Supper point to Christ; neither earns salvation.','Matthew 28:18–20; 1 Corinthians 11:23–32'),('The Church','Christ leads His people in worship, Scripture, prayer, fellowship, and gospel witness.','Acts 2:41–47; Colossians 1:18'),('Assurance of salvation','God keeps His redeemed people secure in Christ, calling them to holy living.','John 10:27–30; Romans 8:38–39'),('Christ’s return','We await Christ’s return, the rapture before the tribulation, and His promised earthly kingdom.','1 Thessalonians 4:13–18; Revelation 19–20')]
mission='As a Christ-centered community, we are committed to engaging those who are exploring faith by proclaiming the gospel of Jesus Christ, through which God alone brings salvation. We also devote ourselves to equipping the saints for the work of ministry and building up the body of Christ in truth and love.'
body=hero('A church family.<br>Centered on Christ.','Bible-based. Christ-centered. Spirit-led. We are Faith Life Community Ministries in Winnipeg.','about-community.jpg','Faith Life church members gathered outdoors',link('#team','Meet our team','button white'))
body+=f'<section class="section gray-section"><div class="wrap editorial-split"><h2>Why we exist.</h2><div><p class="large-copy">{mission}</p><p>John 3:16 · Acts 20:28 · Ephesians 4:11–12</p><h3>A vision that reaches outward.</h3><p>We long to see disciples making disciples, leaders developing leaders, and new congregations growing from the work of the gospel.</p></div></div></section>'
body+='<section class="section" id="team"><div class="wrap"><div class="heading-row"><h2>Meet our team.</h2><p>Serving Christ by caring for His people, teaching His Word, and walking together in faith.</p></div><h3 class="group-title">Our pastors</h3><div class="team-grid">'+''.join(f'<article class="person"><div class="person-monogram" aria-hidden="true">{initials}</div><h3>{name}</h3><p>{role}</p></article>' for name,role,initials in pastors)+'</div><div class="elders-block"><h3>Our elders</h3><div class="elder-list">'+''.join(f'<p>{name}</p>' for name in elders)+'</div></div></div></section>'
values=['Christ-centered living','Gospel proclamation','Spirit-led discipleship','Truth and love','Outreach and compassion','Servant leadership','Church multiplication','Unity in mission']
body+='<section class="section navy-section"><div class="wrap editorial-split"><h2>What shapes<br>our life together.</h2><ol class="values-list">'+''.join(f'<li>{v}</li>' for v in values)+'</ol></div></section>'
body+='<section class="section gray-section" id="beliefs"><div class="wrap"><div class="heading-row"><h2>Statement of faith.</h2><p>The essential beliefs at the heart of our church. Select a topic to read a brief summary.</p></div><div class="beliefs-list">'+''.join(f'<details><summary>{name}<span aria-hidden="true">＋</span></summary><div><p>{desc}</p><p class="scripture-ref">{ref}</p></div></details>' for name,desc,ref in beliefs)+'</div><p class="source-note">These summaries follow our published Essential Beliefs. '+link('https://flcmonline.com/essential-beliefs/','Read the full statement','text-link')+'</p></div></section>'
