# MINISTRIES
programs=[('Discovery Bible Study','faith','Explore the foundations of Christian faith and bring your questions about Jesus and the Bible.'),('New Believer Follow-Up','faith','Keep growing in Scripture, discipleship, and everyday Christian living after your first steps of faith.'),("Children’s Sunday School",'children','Bible stories, music, crafts, and age-appropriate lessons help children learn about God and grow in faith.'),('Friday Youth Night','youth','Teens gather for Bible teaching, conversation, games, music, and friendship in a Christ-centered community.'),('Young Adult Bible Study','youth','Explore Scripture and the questions of young adulthood with others walking through a similar season.'),("Men’s Bible Study",'adults','Study Scripture, encourage one another, and grow in faithful living at home and in the community.'),("Women’s Bible Study",'adults','Grow in biblical understanding and encourage one another through prayer, conversation, and practical application.'),('Young Couple Fellowship','adults','Build a Christ-centered home through biblical conversation, encouragement, and friendships with other couples.'),('Wednesday Prayer Meeting','prayer','Seek God together in prayer, Scripture, and worship, sharing burdens and lifting up others.'),("Men’s Fellowship",'adults','Build relationships and encourage one another through shared life, conversation, and service.'),("Women’s Fellowship",'adults','Connect through prayer, encouragement, and Christ-centered friendships across the seasons of life.'),('Annual Family Camp','family','Step away from everyday routines for worship, teaching, outdoor activities, and time together as a church family.')]
body=hero('Find your people.<br>Grow in faith.','Gatherings for every season of life, with Scripture and community at the center.','ministries-fellowship.jpg','Young people spending time together in a home',link('#groups','Explore our groups','button white'))
body+='<section class="section gray-section" id="groups"><div class="wrap"><div class="heading-row"><h2>A place to connect.</h2><p>Explore a group, then contact our team for the current meeting time and location.</p></div><div class="directory-tools"><label for="program-search">Find a ministry<input id="program-search" type="search" placeholder="Search ministries" autocomplete="off"></label><div class="filter-chips" aria-label="Filter ministries">'+''.join(f'<button type="button" data-program-filter="{k}" aria-pressed="{str(k=="all").lower()}">{v}</button>' for k,v in [('all','All'),('faith','Explore faith'),('children','Children'),('youth','Youth & young adults'),('adults','Adults'),('prayer','Prayer'),('family','Family')])+'</div></div><p id="program-count" class="filter-count" aria-live="polite">12 ministries</p><div class="program-grid">'+''.join(f'<article data-program-category="{cat}" class="program-card"><h3>{name}</h3><p>{desc}</p>{link("contact.html?topic="+html.escape(name,quote=True),"Ask about this ministry","text-link")}</article>' for name,cat,desc in programs)+'</div><p id="program-empty" hidden>No ministries match your search. Try another word or choose All.</p></div></section>'
body+='<section class="section"><div class="wrap editorial-split"><h2>Not sure<br>where to start?</h2><div><p class="large-copy">You do not have to figure it out alone.</p><p>Tell us a little about your season of life and what you are looking for. We would love to help you take a next step.</p>'+link('contact.html','Talk with our team')+'</div></div></section>'+cta('Gather with us.','See the regular gatherings that keep our community connected.','events.html','Explore events')
page('ministries','Ministries','Discover Bible studies, youth gatherings, prayer, family programs, and fellowship at Faith Life.',body)
# MESSAGES
body=hero('The Word.<br>For everyday life.','Listen to the teaching ministry of Faith Life Community Ministries, wherever your week takes you.','messages-still-life.png','A Bible and microphone on a quiet desk',link('#listen','Listen now','button white'))
body+=f'<section class="section gray-section" id="listen"><div class="wrap message-layout"><div><h2>Listen & grow.</h2><p>Our Spotify podcast brings the church’s messages into your week. Revisit a message, explore a series, or share an episode with a friend.</p>{link(SPOTIFY,"Open the full podcast")}</div><div class="podcast-shell"><iframe title="Faith Life messages on Spotify" src="https://open.spotify.com/embed/show/17Y9zFZ4U2Cj9gBXXc7O8G?utm_source=generator&theme=0" height="352" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" allowfullscreen loading="lazy"></iframe><p>To browse the full episode library or listen in the app, open the podcast on Spotify.</p></div></div></section>'
body+='<section class="section"><div class="wrap"><div class="heading-row"><h2>Let the Word<br>shape your week.</h2><p>A few simple ways to carry what you hear into everyday life.</p></div><div class="steps-grid"><article><span>01</span><h3>Return to Scripture.</h3><p>Read the passage for yourself. Notice its context and what it reveals about God.</p></article><article><span>02</span><h3>Pray honestly.</h3><p>Bring your questions to God. Ask Him to grow your understanding and help you respond.</p></article><article><span>03</span><h3>Walk it out.</h3><p>Choose one step of obedience and share what you are learning with someone in your community.</p></article></div></div></section>'+cta('Keep exploring.','Find reflections to help connect biblical truth with everyday life.','articles.html','Read the articles')
page('messages','Messages','Listen to Faith Life Community Ministries messages through our Spotify podcast.',body)
# VISIT
body=hero('Come as you are.<br>We’ll meet you here.','Exploring faith or looking for a church home? We would love to welcome you to Faith Life.','visit-gathering.jpg','People listening together during a Faith Life church service',link('#find-us','Find us','button white'))
body+=f'<section class="section gray-section" id="find-us"><div class="wrap editorial-split"><h2>Your first visit.</h2><div><h3>427 Matheson Avenue</h3><p>Winnipeg, Manitoba R2V 3A7</p><p>Connect with our team before you come to confirm the current service time and ask any questions about your visit.</p><div class="actions">{link("contact.html","Ask about Sunday")}{link(MAP,"Get directions","text-link")}</div></div></div></section>'
body+='<section class="section"><div class="wrap"><div class="heading-row"><h2>A little of what<br>you can expect.</h2><p>A local church family learning to follow Jesus together.</p></div><div class="steps-grid"><article><span>01</span><h3>Worship & the Word</h3><p>We gather around Scripture, prayer, and worship, with Jesus at the center.</p></article><article><span>02</span><h3>People to meet</h3><p>There is room for conversation and connection. Introduce yourself and let us know it is your first visit.</p></article><article><span>03</span><h3>A next step</h3><p>Explore a Bible study, join a gathering, or keep asking questions about the Christian faith.</p></article></div></div></section>'
faqs=[('What time is the service?','Please contact the church to confirm the current Sunday service time before your first visit.'),('What should I wear?','Come in clothing you feel comfortable in. You are welcome to join us as you are.'),('Is there something for children?',"Children’s Sunday School is part of our ministry. Contact the team for current age groups and arrangements."),('Can I come if I am exploring Christianity?','Yes. You are welcome to listen, ask honest questions, and get to know the community.'),('How can I connect after visiting?','Explore the Ministries page or talk with our team about a Bible study or fellowship group.')]
