body+='<section class="section gray-section"><div class="wrap"><div class="news-feature"><div><h2>Messages that go<br>with you.</h2><p>Our teaching ministry is available on Spotify. Revisit a Sunday message or share an episode with someone you know.</p>'+link('messages.html','Explore messages')+'</div><div class="news-callout"><span aria-hidden="true">↗</span><h3>Faith Life<br>Community Podcast</h3>'+link(SPOTIFY,'Listen on Spotify','text-link')+'</div></div></div></section>'
