body=hero('Let’s connect.','A first visit, a question about faith, or a place to get involved. We would love to hear from you.')
body+=f'<section class="section gray-section"><div class="wrap contact-layout"><div><h2>Say hello.</h2><p>Send a message to our church team through the Faith Life contact form.</p><p id="contact-topic" class="contact-topic" hidden></p>{link("https://flcmonline.com/contact-us/","Open the church contact form")}<p class="contact-helper">You’ll continue to the church’s existing contact form to send your message.</p></div><div class="contact-address"><h3>Find us in Winnipeg.</h3><address>427 Matheson Avenue<br>Winnipeg, Manitoba<br>R2V 3A7</address>{link(MAP,"Get directions","text-link")}<p>For Sunday service times and group schedules, please check with our team before coming.</p></div></div></section>'
