s=s.replace('https://flcmonline.com/about-flcm/','about.html').replace('https://flcmonline.com/essential-beliefs/','about.html#beliefs').replace('https://flcmonline.com/programs/','ministries.html').replace('https://flcmonline.com/contact-us/','contact.html')
